css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 8px 12px; margin-bottom: 10px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; margin-bottom: 4px; display: flex; align-items: center; gap: 6px;}
.mz .recuerda-idea{font-size: 12.5px; margin-bottom: 4px; line-height: 1.35;}
.mz .recuerda-idea strong{font-weight: 700;}
.mz .recuerda-semana{display: flex; justify-content: space-between; gap: 4px; margin-top: 6px; flex-wrap: nowrap;}
.mz .rs-dia{flex: 1; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 4px 2px; text-align: center; font-size: 12px; font-weight: 700;}
.mz .rs-dia.findesemana{background: #eee;}
.mz .numerar-grid{display: grid; grid-template-columns: repeat(2, 1fr); gap: 5px 28px;}
.mz .numerar-fila{display: flex; align-items: center; gap: 12px; font-size: 14px; font-weight: 600;}
.mz .numerar-hueco{width: 38px; height: 28px; border: 1.5px solid var(--bosque); border-radius: 5px;}
.mz .ordenar-fila{display: grid; grid-template-columns: repeat(7, 1fr); gap: 5px;}
.mz .ordenar-caja{border: 1.5px solid var(--bosque); border-radius: 6px; min-height: 42px; display: flex; align-items: center; justify-content: center; font-size: 12.5px; font-weight: 700; text-align: center; padding: 3px;}
.mz .ordenar-caja.lleno{background: #f4f4f4;}
.mz .ordenar-caja.hueco{background: #fff;}
.mz .rodear-fila{display: grid; grid-template-columns: repeat(7, 1fr); gap: 6px;}
.mz .rodear-caja{border: 1.5px dashed #000; border-radius: 50px; padding: 12px 4px; text-align: center; font-size: 12.5px; font-weight: 700;}
.mz .frases{display: flex; flex-direction: column; gap: 5px;}
.mz .frase{font-size: 13px; line-height: 1.45;}
.mz .hueco-linea{display: inline-block; min-width: 110px; border-bottom: 1.5px solid var(--bosque); height: 18px; vertical-align: bottom; margin: 0 3px;}
.mz .hoy-tabla{width: 100%; border-collapse: collapse;}
.mz .hoy-tabla th,.mz .hoy-tabla td{border: 1.5px solid var(--bosque); padding: 5px 6px; text-align: center; font-size: 12.5px; height: 30px;}
.mz .hoy-tabla th{font-weight: 700; background: #f4f4f4;}
.mz .hoy-tabla td.lleno{font-weight: 700; background: #fafafa;}
.mz .frase,.mz .recuerda-idea{line-height: 1.875 !important;}
